      de: ["Bergige Landschaft.", "Gepard-Beobachtungen.", "Wandern mit Kindern.", "Gegründet 1937."],
      hu: ["Hegyvidéki táj.", "Gepárd-megfigyelések.", "Túrázás gyerekekkel.", "1937-ben alapították."],
